  ["highground.coachpreferences.bar_textures_colours_and_borders_are_shared.cbec37"] = "Les textures, les couleurs et les bordures des barres sont partagées. Ajustez la taille de chaque panneau dans la page Apparence de son propre addon.",
  ["highground.coachpreferences.settings_live_with_their_addon.f2c359"] = "Les paramètres se trouvent dans leur addon",
  ["highground.coachpreferences.use_an_addon_s_settings_appearance_commands.b1a987"] = "Utilisez les pages Paramètres, Apparence, Commandes, et Aperçus et guide d'un addon. Les panneaux de champ de bataille utilisent /hg bg test. Exécutez /hg test ou /hg test stop depuis Aide et commandes pour basculer ou arrêter tous les aperçus. Aperçu et activation détermine si l'addon s'exécute après le rechargement. Les préférences partagées affectent tous les addons.",
  ["highground.coachpreferences.keep_the_panels_you_want.abbf0b"] = "Gardez les panneaux que vous voulez",
  ["highground.coachpreferences.choose_shared_preferences.f69dd0"] = "Choisir des préférences partagées",
  ["highground.coachpreferences.checked_means_enabled_all_available_feature_switches.16b69f"] = "Coché signifie activé. Tous les commutateurs de fonction disponibles sont affichés ici ; faites défiler pour voir le reste.",
