  ["highground.coachpreferences.the_battlegrounds_nearby_and_bounties_links_open.676c0b"] = "Les liens Champs de bataille, Nearby et Primes ouvrent directement leurs contrôles de texte et de son. Les addons désactivés deviennent disponibles une fois activés dans Addons, après un rechargement.",
  ["highground.coachpreferences.click_battlegrounds_or_next_to_open_its.68ede3"] = "Cliquez sur Champs de bataille, ou sur Suivant pour ouvrir ses contrôles d'alerte.",
  ["highground.coachpreferences.enemy_stealth_stays_available_here_even_when.63bf57"] = "« Camouflage ennemi » reste disponible ici même quand un addon est désactivé.",
  ["highground.coachpreferences.choose_text_sound_or_both.306e9e"] = "Choisissez le texte, le son ou les deux",
  ["highground.coachpreferences.highground_is_the_only_download_you_need.f138df"] = "Highground est le seul téléchargement dont vous avez besoin",
  ["highground.coachpreferences.addons_brings_the_addon_switches_settings_shortcuts.df8aff"] = "Addons rassemble les commutateurs d'addon, les raccourcis de paramètres et les guides. Supprimez tous les téléchargements autonomes séparés. Gardez chaque dossier de module et les deux addons de données requis. Désactiver un addon de données empêche le chargement de Highground.",
