  ["highground.coachpreferences.choose_which_addons_run.892aae"] = "Choisissez les addons à exécuter",
  ["highground.coachpreferences.enable_addon_is_the_same_per_character.e05474"] = "Activer l'addon est le même commutateur par personnage que la liste des AddOns de WoW. Les six sous-addons sont inclus dans le téléchargement Highground.",
  ["highground.coachpreferences.these_are_real_switches_you_can_continue.862243"] = "Ce sont de vrais commutateurs. Vous pouvez continuer sans rien changer.",
  ["highground.coachpreferences.visit_settings_or_replay_a_guide.e879b6"] = "Visiter les paramètres ou rejouer un guide",
  ["highground.coachpreferences.visit_opens_this_addon_s_overview_and.64e863"] = "Visiter ouvre l'aperçu et les paramètres de cet addon. Commencer, Reprendre ou Rejouer ouvre son parcours et conserve sa progression enregistrée.",
  ["highground.coachpreferences.visit_leaves_this_walkthrough_next_continues_without.da36c5"] = "Visiter quitte ce parcours. Suivant continue sans visiter.",
  ["highground.coachpreferences.recognize_subaddons_in_the_sidebar.8ccd1c"] = "Reconnaître les sous-addons dans la barre latérale",
  ["highground.coachpreferences.each_subaddon_has_a_small_crest_and.3b587c"] = "Chaque sous-addon a un petit blason et une bande de couleur. Développez sa section pour Aperçu et activation, Paramètres, Apparence (si disponible), Commandes, et Aperçus et guide.",
  ["highground.coachpreferences.shared_preferences_saved_setups_and_help_apply.3e1969"] = "Les préférences partagées, les configurations enregistrées et l'aide s'appliquent au-delà d'un addon individuel.",
  ["highground.coachpreferences.keep_your_settings_when_disabling_an_addon.518274"] = "Gardez vos paramètres lors de la désactivation d'un addon",
  ["highground.coachpreferences.changing_a_switch_takes_effect_after_reload.145c67"] = "Le changement d'un commutateur prend effet après rechargement. Les préférences de panneau et les enregistrements sauvegardés restent intacts. Afficher le panneau sur les cartes Nearby et Arène ne change que la préférence du panneau. Remettre Activer l'addon à son état initial avant de recharger annule ce changement.",
  ["highground.coachpreferences.profiles_do_not_enable_or_disable_addons.a7920d"] = "Les profils n'activent ni ne désactivent les addons.",
  ["highground.coachpreferences.reload_when_you_are_ready.225a57"] = "Recharger quand vous êtes prêt",
  ["highground.coachpreferences.after_changing_a_switch_reload_to_apply.8a851b"] = "Après avoir changé un commutateur, Recharger pour appliquer apparaît sur Addons. Rechargez en dehors du combat pour démarrer les modules activés et arrêter ceux désactivés. Le guide ne se recharge jamais automatiquement.",
  ["highground.coachpreferences.next_continues_without_reloading.acc474"] = "Suivant continue sans recharger.",
  ["highground.coachpreferences.find_commands_and_their_controls.a1ca25"] = "Rechercher des commandes et leurs contrôles",
  ["highground.coachpreferences.each_addon_has_a_commands_page_help.cc07e2"] = "Chaque addon a une page Commandes ; Aide et commandes les combine. Chaque commande utilise une ligne. Passez la souris pour la syntaxe complète et les alias. Le bouton ouvre les paramètres, exécute l'action ou ouvre des champs étiquetés pour ses valeurs.",
  ["highground.coachpreferences.browsing_is_safe_action_buttons_can_change.33ba22"] = "La navigation est sans risque. Les boutons d'action peuvent modifier les paramètres réels ; ce guide n'y clique pas.",
  ["highground.coachpreferences.discover_channel_members.5df463"] = "Découvrir les membres du canal",
  ["highground.coachpreferences.your_own_character_counts_immediately_a_complete.2a1246"] = "Votre propre personnage compte immédiatement. Une liste complète des membres du canal ajoute d'autres membres avant que leurs annonces d'addon n'arrivent. Actualiser les membres affiche un indicateur de chargement et reste désactivé pendant l'attente. Essayez-le pour voir un exemple de départ.",
  ["highground.coachpreferences.this_sample_does_not_request_a_live.d4e060"] = "Cet exemple ne demande pas une liste de membres en direct ni n'envoie de messages.",
  ["highground.coachpreferences.membership_and_version_reports_are_different.84c36a"] = "Les rapports d'appartenance et de version sont différents",
  ["highground.coachpreferences.a_channel_member_may_not_have_a.590af5"] = "Un membre du canal peut ne pas avoir d'addon qui répond. Les membres sans annonce ont leur propre compte. Les versions proviennent uniquement des annonces reçues ; vérifiez les avis de mise à jour dans votre gestionnaire d'addons.",
  ["highground.coachpreferences.keep_useful_counts_when_a_list_is.120802"] = "Conserver des comptes utiles lorsqu'une liste est indisponible",
  ["highground.coachpreferences.an_incomplete_or_unavailable_member_list_keeps.d5bf62"] = "Une liste de membres incomplète ou indisponible conserve brièvement la dernière liste complète, puis revient aux annonces récentes. Les comptes peuvent inclure des personnages qui sont partis depuis. La découverte de groupe et de guilde utilise toujours les annonces.",
  ["highground.coachpreferences.close_the_guide_to_return_to_live.65ab77"] = "Fermez le guide pour revenir aux comptes en direct. Les préférences de découverte sont désactivées uniquement dans cet exemple.",
